// Finds an index of a minimum element in a[s..e).
// Preconditions (assumed true as per problem statement):
// - a.len() > 0
// - 0 <= s < e <= a.len()
pub fn find_min_index(a: &[i32], s: usize, e: usize) -> usize {
    let mut min_i = s;
    for i in (s + 1)..e {
        if a[i] < a[min_i] {
            min_i = i;
        }
    }
    min_i
}

